class Solution {
public:
    int distributeCookies(vector<int>& cookies, int k) {
        int n = cookies.size();
        int full = 1 << n;
        vector<int> sum(full, 0);
        for (int mask = 0; mask < full; mask++) {
            int s = 0;
            for (int i = 0; i < n; i++) {
                if (mask & (1 << i)) s += cookies[i];
            }
            sum[mask] = s;
        }
        vector<int> dp = sum; // c = 1: one child gets all bags in mask
        for (int c = 2; c <= k; c++) {
            vector<int> ndp(full, INT_MAX);
            for (int mask = 0; mask < full; mask++) {
                for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
                    int rest = mask ^ sub;
                    int val = max(dp[rest], sum[sub]);
                    if (val < ndp[mask]) ndp[mask] = val;
                }
                // sub = 0: child gets nothing, rest = mask
                if (dp[mask] < ndp[mask]) ndp[mask] = dp[mask];
            }
            dp = move(ndp);
        }
        return dp[full - 1];
    }
};
